// Match Shopify line items against Amount Reference SKU masters (with -COLOUR wildcard)
// + title fallback (gfz/gavin in title or variant_title), respecting EXCLUDE_SKUS.
// Output one row per matching line item in the 12-column Mar 2026 schema.

const refRows = $input.all().map(it => it.json);

function parsePrice(s) {
  if (s === undefined || s === null || s === '') return 0;
  const m = String(s).replace(/[$,\s]/g, '').match(/-?\d+(?:\.\d+)?/);
  return m ? parseFloat(m[0]) : 0;
}
function escRegex(s) { return s.replace(/[.+?^${}()|[\]\\]/g, '\\$&'); }

const masters = [];
for (const r of refRows) {
  const sku = String(r['SKU'] || '').trim();
  if (!sku) continue;
  const listing  = parsePrice(r['Listing Price']);
  const fee      = parsePrice(r['3DPS + Stripe Fee (3.4%)']);
  const takehome = parsePrice(r['Gavin Amount (Takehome)']);
  const pat = sku.includes('COLOUR')
    ? '^' + escRegex(sku).replace(/COLOUR/g, '.+') + '$'
    : '^' + escRegex(sku) + '$';
  masters.push({ sku, listing, fee, takehome, re: new RegExp(pat, 'i') });
}
function findMaster(sku) {
  if (!sku) return null;
  for (const m of masters) if (m.re.test(sku)) return m;
  return null;
}

const excludeStr = $('Set Parameters').first().json.EXCLUDE_SKUS || '';
const excludeRegexes = excludeStr.split(',').map(s => s.trim()).filter(Boolean).map(pat => {
  return new RegExp('^' + escRegex(pat).replace(/\\\*/g, '.*') + '$', 'i');
});
function isExcluded(sku) {
  if (!sku) return false;
  return excludeRegexes.some(re => re.test(sku));
}

function titleHints(li) {
  const t = ((li.title || '') + ' ' + (li.variant_title || '')).toLowerCase();
  return t.includes('gfz') || t.includes('gavin');
}

const MON = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
function fmtDate(iso) {
  if (!iso) return '';
  const d = new Date(iso);
  if (isNaN(d.getTime())) return iso.split('T')[0];
  return d.getDate() + ' ' + MON[d.getMonth()] + ' ' + d.getFullYear();
}
function fmtSGD(n) { return '$' + Number(n).toFixed(2); }

const pages = $('Fetch All Orders (paginated)').all();
const orders = pages.flatMap(p => p.json.orders || []);
const rows = [];

for (const o of orders) {
  for (const li of (o.line_items || [])) {
    if (isExcluded(li.sku)) continue;
    const m = findMaster(li.sku);
    const titleHit = !m && titleHints(li);
    if (!m && !titleHit) continue;

    const firstName = (o.customer && o.customer.first_name) || '';
    const lastName  = (o.customer && o.customer.last_name)  || '';
    const name = (firstName + ' ' + lastName).trim() || 'Guest';
    const orderNo = o.order_number != null ? String(o.order_number) : String(o.name || '').replace('#','');
    const qty = li.quantity || 1;

    let listing, fee, takehome, remarks;
    if (m) {
      listing  = fmtSGD(m.listing);
      fee      = fmtSGD(m.fee);
      takehome = fmtSGD(m.takehome);
      remarks  = '';
    } else {
      const liPrice = parseFloat(li.price || 0);
      listing  = fmtSGD(liPrice * qty);
      fee      = '';
      takehome = '';
      remarks  = 'TITLE MATCH - add to Amount Reference?';
    }

    rows.push({
      json: {
        'Order No.':                orderNo,
        'Date':                     fmtDate(o.created_at),
        'Name':                     name,
        'Email':                    o.email || '',
        'Gdrive access':            '',
        'SKU':                      li.sku || '',
        'Listing Price':            listing,
        '3DPS+Stripe Fee':          fee,
        'Gavin Amount (Takehome)':  takehome,
        'Payment Complete':         '',
        'Date of Payment':          '',
        'Remarks':                  remarks,
      }
    });
  }
}

return rows;

